mapper.select:
SELECT r.id, r.occurrence_time AS occurrenceTime, r.fault_type AS faultType, r.fault_description AS faultDescription, r.repair_result AS repairResult, r.completion_time AS completionTime, r.repair_hours AS repairHours, r.repair_priority AS repairPriority, r.responsibility_division AS responsibilityDivision, r.equipment_id AS equipmentId, r.staff_id AS staffId, s.name AS staffName FROM maintenance_record r LEFT JOIN maintenance_staff s ON r.staff_id = s.id
r.deleted = 0
AND r.fault_type LIKE CONCAT('%', #{faultType}, '%')
AND r.repair_priority = #{repairPriority}
AND r.equipment_id = #{equipmentId}
AND r.staff_id = #{staffId}
AND r.occurrence_time >= #{startTime}
AND r.occurrence_time <= #{endTime}
ORDER BY r.occurrence_time DESC

SELECT * FROM maintenance_record

    deleted = 0

        AND fault_type LIKE CONCAT('%', #{faultType}, '%')


        AND repair_priority = #{repairPriority}


ORDER BY ${sortField} ${sortOrder} LIMIT #{offset}, #{limit}
